import { createComponentConfig, createElementConfig, } from "../../core/config/component.js";
import { TEXT_FIELD_DEFAULTS } from "./constants.js";
export const defaultConfig = {
    type: TEXT_FIELD_DEFAULTS.TYPE,
    variant: TEXT_FIELD_DEFAULTS.VARIANT,
};
export const createBaseConfig = (config = {}) => createComponentConfig(defaultConfig, config, "text-field");
export const getElementConfig = (config) => createElementConfig(config, {
    tag: "div",
    className: config.class,
});
export const getApiConfig = (comp) => ({
    disabled: {
        enable: comp.disabled.enable,
        disable: comp.disabled.disable,
        isDisabled: comp.disabled.isDisabled,
    },
    lifecycle: {
        destroy: comp.lifecycle.destroy,
    },
});
export default defaultConfig;
